namespace {
bool json_diagnostics(const std::vector<std::string>& args){for(std::size_t i=0;i+1<args.size();++i)if(args[i]=="--diagnostic-format"&&args[i+1]=="json")return true;return false;}
int fail(const Diagnostic& d,bool json){std::cerr<<(json?diagnostic_json(d):diagnostic_human(d))<<'\n';return 1;}
void usage(){std::cerr<<"usage: stellar version | check FILE | fmt FILE [--check] | inspect TARGET [--view VIEW] | test MANIFEST | package MANIFEST (--output FILE | --verify FILE) | build MANIFEST --output DIR --stdlib DIR [--verify-build-lock FILE]\n";}
std::string folded_path(const std::filesystem::path& path){auto value=std::filesystem::weakly_canonical(path).generic_string();std::transform(value.begin(),value.end(),value.begin(),[](unsigned char c){return static_cast<char>(std::tolower(c));});while(value.size()>1&&value.back()=='/')value.pop_back();return value;}
bool path_contains(const std::string& root,const std::string& candidate){return candidate==root||(candidate.size()>root.size()&&candidate.starts_with(root)&&candidate[root.size()]=='/');}
}
int main(int argc,char** argv){_setmode(_fileno(stdout),_O_BINARY);_setmode(_fileno(stderr),_O_BINARY);std::vector<std::string> args;for(int i=1;i<argc;++i)args.emplace_back(argv[i]);if(args.empty()){usage();return 2;}if(args[0]=="version"){if(args.size()!=1){usage();return 2;}std::cout<<"Stellar 0.1.0 (windows-x86_64-msvc; stellar-lab-v0)\n";return 0;}const bool json=json_diagnostics(args);
if(args[0]=="build"){
  if(args.size()!=6&&args.size()!=8&&args.size()!=10){usage();return 2;}std::string output,stdlib,verify;for(std::size_t i=2;i<args.size();i+=2){if(args[i]=="--output")output=args[i+1];else if(args[i]=="--stdlib")stdlib=args[i+1];else if(args[i]=="--verify-build-lock")verify=args[i+1];else if(args[i]=="--diagnostic-format"&&args[i+1]=="json"){}else{usage();return 2;}}if(output.empty()||stdlib.empty()){usage();return 2;}const auto package_root=folded_path(std::filesystem::absolute(args[1]).parent_path()),output_root=folded_path(std::filesystem::absolute(output));if(path_contains(package_root,output_root)||path_contains(output_root,package_root)){Diagnostic error{"S6003","error","native build output must be separate from the package root",std::filesystem::absolute(output).generic_string(),{},"choose a new output directory outside the reviewed package tree"};return fail(error,json);}
  const auto compiler=std::filesystem::absolute(argv[0]).string();const auto script=std::filesystem::absolute(argv[0]).parent_path()/"build-package.ps1";if(!std::filesystem::is_regular_file(script)){Diagnostic error{"S6001","error","native build driver is unavailable",script.generic_string(),{},"install build-package.ps1 beside stellar.exe"};return fail(error,json);}std::vector<std::string> values{"powershell.exe","-NoProfile","-ExecutionPolicy","Bypass","-File",script.string(),"-Compiler",compiler,"-Manifest",std::filesystem::absolute(args[1]).string(),"-OutputDirectory",std::filesystem::absolute(output).string(),"-StdlibRoot",std::filesystem::absolute(stdlib).string(),"-DiagnosticFormat",json?"json":"human"};if(!verify.empty()){values.push_back("-VerifyBuildLock");values.push_back(std::filesystem::absolute(verify).string());}std::vector<const char*> spawned;for(const auto&value:values)spawned.push_back(value.c_str());spawned.push_back(nullptr);const auto result=_spawnvp(_P_WAIT,"powershell.exe",spawned.data());if(result!=0)return result<0?1:static_cast<int>(result);return 0;
}
if(args[0]=="__emit-native-package"&&args.size()==3){PackageGraphAnalysis package;Diagnostic error;if(!analyze_package_graph(args[1],package,error,true))return fail(error,json);if(!verify_dependency_lock(args[1],package,error))return fail(error,json);if(!write_native_package_plan(args[1],args[2],package,error))return fail(error,json);std::cout<<"native plan: ok\n";return 0;}
if(args[0]=="run"){Diagnostic error{"S7001","error","native run is disabled until the mandatory authorization and OS-isolation gate passes",args.size()>1?std::filesystem::absolute(args[1]).generic_string():"",{},"use check/test/build/inspect; checksum integrity is not authorization"};return fail(error,json);}
if(args[0]=="test"&&(args.size()==2||(args.size()==4&&args[2]=="--diagnostic-format"&&args[3]=="json"))){std::string result;Diagnostic error;if(!test_package_without_execution(args[1],result,error))return fail(error,json);std::cout<<result<<'\n';return 0;}
if(args[0]=="package"&&(args.size()==4||args.size()==6)){std::string mode,value;bool valid=true;for(std::size_t i=2;i<args.size();i+=2){if(args[i]=="--output"||args[i]=="--verify"){if(!mode.empty())valid=false;mode=args[i];value=args[i+1];}else if(args[i]=="--diagnostic-format"&&args[i+1]=="json"){}else valid=false;}if(!valid||mode.empty()){usage();return 2;}std::string result;Diagnostic error;const auto schema_root=std::filesystem::absolute(argv[0]).parent_path()/"schemas";const std::filesystem::path output=mode=="--output"?std::filesystem::path(value):std::filesystem::path{};const std::filesystem::path verify=mode=="--verify"?std::filesystem::path(value):std::filesystem::path{};if(!create_or_verify_bundle(args[1],schema_root,output,verify,result,error))return fail(error,json);std::cout<<result<<'\n';return 0;}
if((args[0]=="check"||args[0]=="fmt")&&args.size()>=2){Source source;Diagnostic error;if(!load_source(args[1],source,error))return fail(error,json);Program program;if(!check_source(source,program,error))return fail(error,json);if(args[0]=="check"){std::cout<<(json?"{\"status\":\"ok\"}\n":"check: ok\n");return 0;}const auto formatted=format_program(program);bool check=false;for(const auto&a:args)if(a=="--check")check=true;if(check)return formatted==source.text?0:1;std::cout<<formatted;return 0;}if(args[0]=="inspect"&&(args.size()==2||args.size()==4||args.size()==6)){std::string view;bool valid=true;for(std::size_t i=2;i<args.size();i+=2){if(args[i]=="--view")view=args[i+1];else if(args[i]=="--diagnostic-format"&&args[i+1]=="json"){}else valid=false;}if(!valid){usage();return 2;}std::string result;Diagnostic error;if(!inspect_developer_view(args[1],view,result,error))return fail(error,json);std::cout<<result<<'\n';return 0;}if((args[0]=="check-package"||args[0]=="inspect-package")&&args.size()>=2){PackageGraphAnalysis package;Diagnostic error;if(!analyze_package_graph(args[1],package,error))return fail(error,json);bool write=false,verify=false;for(const auto&a:args){if(a=="--write-dependency-lock")write=true;if(a=="--verify-dependency-lock")verify=true;}if(write&&!write_dependency_lock(args[1],package,error))return fail(error,json);if(verify&&!verify_dependency_lock(args[1],package,error))return fail(error,json);if(args[0]=="inspect-package")std::cout<<package.json<<'\n';else std::cout<<(json?"{\"status\":\"ok\"}\n":"package check: ok\n");return 0;}if(args[0]=="inspect-manifest"&&args.size()>=2){PackageInspection result;Diagnostic error;if(!inspect_manifest(args[1],result,error))return fail(error,json);bool write=false,verify=false;for(const auto&a:args){if(a=="--write-lock")write=true;if(a=="--verify-lock")verify=true;}if(write&&!write_lock(args[1],result,error))return fail(error,json);if(verify&&!verify_lock(args[1],result,error))return fail(error,json);std::cout<<inspection_json(result)<<'\n';return 0;}usage();return 2;}
